self.go_to_xy(-150, -50)

speed = 3

x_limit = 210
y_limit = 145

while True:
    if self.key_pressed("ArrowLeft") and self.x_position > -x_limit:
        self.change_x(-speed)
    if self.key_pressed("ArrowRight") and self.x_position < x_limit:
        self.change_x(speed)
    if self.key_pressed("ArrowDown") and self.y_position > -y_limit:
        self.change_y(-speed)
    if self.key_pressed("ArrowUp") and self.y_position < y_limit:
        self.change_y(speed)

self.go_to_xy(0, 75)

speed = 3

x_limit = 200
y_limit = 140

x_velocity = 0
y_velocity = 0

accel = 0.5

while True:
    if self.key_pressed("j"):
        x_velocity -= accel
        x_velocity = max(x_velocity, -speed)
    if self.key_pressed("l"):
        x_velocity += accel
        x_velocity = min(x_velocity, speed)
    if not self.key_pressed("j") and not self.key_pressed("l"):
        if x_velocity > 0:
            x_velocity -= accel
        elif x_velocity < 0:
            x_velocity += accel

    self.change_x(x_velocity)
    self.set_x(min(x_limit, self.x_position))
    self.set_x(max(-x_limit, self.x_position))

    if self.key_pressed("k"):
        y_velocity -= accel
        y_velocity = max(y_velocity, -speed)
    if self.key_pressed("i"):
        y_velocity += accel
        y_velocity = min(y_velocity, speed)
    if not self.key_pressed("k") and not self.key_pressed("i"):
        if y_velocity > 0:
            y_velocity -= accel
        elif y_velocity < 0:
            y_velocity += accel

    self.change_y(y_velocity)
    self.set_y(min(y_limit, self.y_position))
    self.set_y(max(-y_limit, self.y_position))
